    "ProgramNotificationTemplate.bulkSharing": {
        parameters: {
            query?: {
                assumeTrue?: components["parameters"]["Options.assumeTrue"];
                /** @description Asynchronous import, returns immediately with a _Location_ header pointing to the location of the _importReport_. The payload also contains a json object of the job created. */
                async?: components["parameters"]["MetadataImportParams.async"];
                atomic?: boolean;
                /** @description Sets atomic mode, in the old importer we always did a best effort import, which means that even if some references did not exist, we would still import (i.e. missing data elements on a data element group import). Default for new importer is to not allow this, and similar reject any validation errors. Setting the `NONE` mode emulated the old behavior. */
                atomicMode?: components["parameters"]["MetadataImportParams.atomicMode"];
                /** @description Sets the flush mode, which controls when to flush the internal cache. It is strongly recommended to keep this to `AUTO` (which is the default). Only use `OBJECT` for debugging purposes, where you are seeing hibernate exceptions and want to pinpoint the exact place where the stack happens (hibernate will only throw when flushing, so it can be hard to know which object had issues). */
                flushMode?: components["parameters"]["MetadataImportParams.flushMode"];
                /** @description Sets the identifier scheme to use for reference matching. `AUTO` means try `UID` first, then `CODE`. */
                identifier?: components["parameters"]["MetadataImportParams.identifier"];
                /** @description Sets overall import mode, decides whether or not to only `VALIDATE` or also `COMMIT` the metadata, this has similar functionality as our old dryRun flag. */
                importMode?: components["parameters"]["MetadataImportParams.importMode"];
                /** @description Sets the `ImportReport` mode, controls how much is reported back after the import is done. `ERRORS` only includes ObjectReports for object which has errors. `FULL` returns an ObjectReport for all objects imported, and `DEBUG` returns the same plus a name for the object (if available). */
                importReportMode?: components["parameters"]["MetadataImportParams.importReportMode"];
                /** @description Sets import strategy, `CREATE_AND_UPDATE` will try and match on identifier, if it doesn't exist, it will create the object. */
                importStrategy?: components["parameters"]["MetadataImportParams.importStrategy"];
                lastUpdated?: components["parameters"]["Options.lastUpdated"];
                manage?: components["parameters"]["WebOptions.manage"];
                metadataSyncImport?: components["parameters"]["MetadataImportParams.metadataSyncImport"];
                options?: components["parameters"]["Options.options"];
                /** @description Defines which page number to return. */
                page?: components["parameters"]["WebOptions.page"];
                /** @description Defines the number of elements to return for each page. */
                pageSize?: components["parameters"]["WebOptions.pageSize"];
                /** @description Indicates whether to return lists of elements in pages. */
                paging?: components["parameters"]["WebOptions.paging"];
                /** @description Sets the preheater mode, used to signal if preheating should be done for `ALL` (as it was before with `preheatCache=true`) or do a more intelligent scan of the objects to see what to preheat (now the default), setting this to `NONE` is not recommended. */
                preheatMode?: components["parameters"]["MetadataImportParams.preheatMode"];
                /** @description Combine filters with `AND` (default) or `OR` */
                rootJunction?: components["parameters"]["WebOptions.rootJunction"];
                /** @description Skip sharing properties, does not merge sharing when doing updates, and does not add user group access when creating new objects. */
                skipSharing?: components["parameters"]["MetadataImportParams.skipSharing"];
                skipTranslation?: components["parameters"]["MetadataImportParams.skipTranslation"];
                /** @description Skip validation for import. **NOT RECOMMENDED** */
                skipValidation?: components["parameters"]["MetadataImportParams.skipValidation"];
                user?: components["parameters"]["MetadataImportParams.user"];
                viewClass?: components["parameters"]["WebOptions.viewClass"];
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: {
            content: {
                "application/json-patch+json": components["schemas"]["BulkJsonPatch"];
            };
        };
        responses: {
            /** @description ? */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["WebMessage"];
                };
            };
        };
    };
